[{"order":1,"type":"heading","text":"Chain of Responsibility for Request Processing Pipelines"},{"order":2,"type":"paragraph","text":"The Chain of Responsibility is a behavioral design pattern that lets you pass requests along a chain of handlers. Upon receiving a request, each handler decides either to process the request or to pass it to the next handler in the chain. This pattern is particularly useful for building extensible request processing pipelines in modern software architectures."},{"order":3,"type":"subheading","text":"Core Concepts"},{"order":4,"type":"bullet_point","text":"Handler Interface: Defines the common contract for all concrete handlers, typically including a method to process the request and a way to set the next handler."},{"order":5,"type":"bullet_point","text":"Concrete Handlers: Implement the handler interface, perform the actual processing logic, and decide whether to delegate to the successor."},{"order":6,"type":"bullet_point","text":"Client: Initiates the request to any concrete handler in the chain without needing to know which object ultimately processes it."},{"order":7,"type":"subheading","text":"Implementing a Request Processing Pipeline"},{"order":8,"type":"paragraph","text":"Below is an example of how to implement a modular request processing pipeline in C# where multiple middleware components handle an incoming HTTP-like request sequentially."},{"order":9,"type":"code","text":"public class RequestContext {
    public string Path { get; set; }
    public string Body { get; set; }
    public bool IsAuthenticated { get; set; }
    public Dictionary<string, object> Headers { get; set; } = new();
}

public interface IMiddleware {
    IMiddleware SetNext(IMiddleware next);
    void Handle(RequestContext context);
}

public abstract class BaseMiddleware : IMiddleware {
    private IMiddleware _next;

    public IMiddleware SetNext(IMiddleware next) {
        _next = next;
        return next;
    }

    public virtual void Handle(RequestContext context) {
        _next?.Handle(context);
    }
}"},{"order":10,"type":"subheading","text":"Adding Concrete Handlers"},{"order":11,"type":"paragraph","text":"Next, we create concrete middleware classes for authentication, logging, and input sanitization, chaining them together to form our pipeline."},{"order":12,"type":"code","text":"public class LoggingMiddleware : BaseMiddleware {
    public override void Handle(RequestContext context) {
        Console.WriteLine($"[LOG] Incoming request to: {context.Path}");
        base.Handle(context);
        Console.WriteLine($"[LOG] Outgoing response for: {context.Path}");
    }
}

public class AuthenticationMiddleware : BaseMiddleware {
    public override void Handle(RequestContext context) {
        if (!context.Headers.ContainsKey("Authorization")) {
            throw new UnauthorizedAccessException("Missing authorization header.");
        }
        context.IsAuthenticated = true;
        Console.WriteLine("[AUTH] Request authenticated successfully.");
        base.Handle(context);
    }
}

public class SanitizationMiddleware : BaseMiddleware {
    public override void Handle(RequestContext context) {
        context.Body = context.Body?.Trim().Replace("<script>", string.Empty);
        Console.WriteLine("[SECURITY] Request body sanitized.");
        base.Handle(context);
    }
}"},{"order":13,"type":"subheading","text":"Wiring and Executing the Pipeline"},{"order":14,"type":"paragraph","text":"Finally, we instantiate the handlers, link them together in sequence, and pass a sample request through the pipeline."},{"order":15,"type":"code","text":"public class Program {
    public static void Main() {
        var pipeline = new LoggingMiddleware();
        pipeline
            .SetNext(new AuthenticationMiddleware())
            .SetNext(new SanitizationMiddleware());

        var request = new RequestContext {
            Path = "/api/data",
            Body = "<script>alert('hack');</script>Hello World",
        };
        request.Headers["Authorization"] = "Bearer token123";

        try {
            pipeline.Handle(request);
        } catch (Exception ex) {
            Console.WriteLine($"Pipeline Error: {ex.Message}");
        }
    }
}"},{"order":16,"type":"subheading","text":"Best Practices and Considerations"},{"order":17,"type":"bullet_point","text":"Ensure that every handler explicitly decides whether to invoke the next handler to prevent unintended request termination."},{"order":18,"type":"bullet_point","text":"Keep handlers single-responsibility oriented. If a middleware handles multiple distinct tasks, split it into smaller pipeline steps."},{"order":19,"type":"bullet_point","text":"Be mindful of execution order, as misconfigured sequences (e.g., sanitizing before authenticating) can introduce security vulnerabilities."}]
